describe('Internal Links Navigation', () => {
    beforeEach(() => {
        cy.visit('https://example.com'); // Replace with the actual URL of the application
    });

    it('should open internal links in the same tab', () => {
        cy.get('a[href*="/internal-page"]').click(); // Replace with the actual internal link selector
        cy.url().should('include', '/internal-page'); // Verify the URL has changed to the internal page
        cy.get('h1').should('contain', 'Internal Page Title'); // Verify the content of the internal page
    });

    it('should not open external links in the same tab', () => {
        cy.get('a[href*="https://external.com"]').should('have.attr', 'target', '_blank'); // Replace with the actual external link selector
    });
});
